416	/**
417	 * Attempts to acquire an exclusive lock file using O_CREAT | O_EXCL.
418	 * Returns true if the lock was acquired, false if another instance owns it.
419	 */
420	export async function tryAcquireLock(
421	  lockPath: string,
422	  retries = 1,
423	): Promise<boolean> {
424	  const lockInfo: LockInfo = {
425	    pid: process.pid,
426	    startedAt: new Date().toISOString(),
427	  };
428	
429	  try {
430	    // Atomic create-if-not-exists
431	    const fd = await fs.open(
432	      lockPath,
433	      fsConstants.O_CREAT | fsConstants.O_EXCL | fsConstants.O_WRONLY,
434	    );
435	    try {
436	      await fd.writeFile(JSON.stringify(lockInfo));
437	    } finally {
438	      await fd.close();
439	    }
440	    return true;
441	  } catch (error: unknown) {
442	    if (isNodeError(error) && error.code === 'EEXIST') {
443	      // Lock exists — check if it's stale
444	      if (retries > 0 && (await isLockStale(lockPath))) {
445	        debugLogger.debug('[MemoryService] Cleaning up stale lock file');
446	        await releaseLock(lockPath);
447	        return tryAcquireLock(lockPath, retries - 1);
448	      }
449	      debugLogger.debug(
450	        '[MemoryService] Lock held by another instance, skipping',
451	      );
452	      return false;
453	    }
454	    throw error;
455	  }
456	}
