458	/**
459	 * Checks if a lock file is stale (owner PID is dead or lock is too old).
460	 */
461	export async function isLockStale(lockPath: string): Promise<boolean> {
462	  try {
463	    const content = await fs.readFile(lockPath, 'utf-8');
464	    const parsed: unknown = JSON.parse(content);
465	    if (!isLockInfo(parsed)) {
466	      return true; // Invalid lock data — treat as stale
467	    }
468	    const lockInfo = parsed;
469	
470	    // Check if PID is still alive
471	    try {
472	      process.kill(lockInfo.pid, 0);
473	    } catch {
474	      // PID is dead — lock is stale
475	      return true;
476	    }
477	
478	    // Check if lock is too old
479	    const lockAge = Date.now() - new Date(lockInfo.startedAt).getTime();
480	    if (lockAge > LOCK_STALE_MS) {
481	      return true;
482	    }
483	
484	    return false;
485	  } catch {
486	    // Can't read lock — treat as stale
487	    return true;
488	  }
489	}
