52	async function listSessionFileCandidates(
53	  chatsDir: string,
54	): Promise<SessionFileCandidate[]> {
55	  const allFiles = await fs.readdir(chatsDir);
56	  const candidates: SessionFileCandidate[] = [];
57	
58	  for (const fileName of allFiles) {
59	    if (!isSupportedSessionFile(fileName)) continue;
60	
61	    const filePath = path.join(chatsDir, fileName);
62	    try {
63	      const stat = await fs.stat(filePath);
64	      if (!stat.isFile()) continue;
65	      candidates.push({ filePath, mtimeMs: stat.mtimeMs });
66	    } catch {
67	      // Skip files that disappeared between readdir and stat.
68	    }
69	  }
70	
