72	    const mtimeDelta = b.mtimeMs - a.mtimeMs;
73	    if (mtimeDelta !== 0) {
74	      return mtimeDelta;
75	    }
76	
77	    return path.basename(b.filePath).localeCompare(path.basename(a.filePath));
78	  });
