105	function normalizePathCandidate(
106	  candidate: string,
107	  projectRoot: string,
108	): string | null {
109	  const trimmed = candidate.trim();
110	  if (
111	    trimmed.length === 0 ||
112	    trimmed.length > 240 ||
113	    trimmed.includes('\n') ||
114	    (!trimmed.includes('/') &&
115	      !trimmed.includes('\\') &&
116	      !trimmed.startsWith('.') &&
117	      path.extname(trimmed).length === 0)
118	  ) {
119	    return null;
120	  }
