122	  let normalized = trimmed.replace(/\\/g, '/');
123	  if (path.isAbsolute(trimmed)) {
124	    const relative = path.relative(projectRoot, trimmed);
125	    normalized =
126	      relative && !relative.startsWith('..') && !path.isAbsolute(relative)
127	        ? relative.replace(/\\/g, '/')
128	        : path.basename(trimmed);
129	  }
130	
131	  if (normalized.length > 120) {
132	    normalized = normalized.split('/').slice(-3).join('/');
133	  }
