149	    return;
150	  }
151	
152	  if (typeof value === 'string') {
153	    if (!keyHint || !PATH_KEY_REGEX.test(keyHint)) {
154	      return;
155	    }
156	
157	    const normalized = normalizePathCandidate(value, projectRoot);
158	    if (normalized) {
159	      pushUniqueLimited(paths, normalized, MAX_SCRATCHPAD_PATHS);
160	    }
161	    return;
162	  }
163	
164	  if (Array.isArray(value)) {
165	    for (const item of value) {
166	      collectPathsFromValue(item, projectRoot, paths, keyHint, depth + 1);
167	      if (paths.length >= MAX_SCRATCHPAD_PATHS) {
168	        return;
169	      }
170	    }
171	    return;
172	  }
173	
174	  if (typeof value !== 'object' || value === null) {
175	    return;
176	  }
177	
178	  for (const [key, nestedValue] of Object.entries(value)) {
179	    collectPathsFromValue(nestedValue, projectRoot, paths, key, depth + 1);
180	    if (paths.length >= MAX_SCRATCHPAD_PATHS) {
181	      return;
182	    }
183	  }
